  ('e_0155', 'p_029', 'mahmoud@givefeedback.dev', 'Re: Podcast invite — the founder story', '<p>We bundle tools into monthly retainers for clients. Is there a reseller or referral arrangement we could set up?</p>', 'We bundle tools into monthly retainers for clients. Is there a reseller or referral arrangement we could set up?', '{}', '<e_0155@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 2640994), (CAST(strftime('%s','now') AS INTEGER) - 2640994), NULL, NULL),
  ('e_0156', 'p_029', 'mahmoud@givefeedback.dev', 'Re: Podcast invite — the founder story', '<p>We maintain a few Webflow apps and think GiveFeedback would be a natural listing. Open to co-building an integration?</p>', 'We maintain a few Webflow apps and think GiveFeedback would be a natural listing. Open to co-building an integration?', '{}', '<e_0156@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1356561), (CAST(strftime('%s','now') AS INTEGER) - 1356561), NULL, NULL),
