  ('e_0515', 'p_099', 'mahmoud@givefeedback.dev', 'Speaking slot at our design meetup?', '<p>We run a 200-person design meetup in Lisbon next month. Would you give a lightning talk on the feedback-to-tasks workflow?</p><p>Happy to hop on a quick call if that''s easier than going back and forth over email.</p>', 'We run a 200-person design meetup in Lisbon next month. Would you give a lightning talk on the feedback-to-tasks workflow?

Happy to hop on a quick call if that''s easier than going back and forth over email.', '{}', '<e_0515@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1234378), (CAST(strftime('%s','now') AS INTEGER) - 1234378), '[{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', NULL),
  ('e_0516', 'p_g00', 'support@givefeedback.dev', 'Clicks not captured in Safari replays', '<p>Our client records their feedback in Safari and the replays are missing every click — voice and screen are fine, but the cursor never lands anywhere. Chrome sessions look perfect. Looping in Tomas, who set up the embed.</p>', 'Our client records their feedback in Safari and the replays are missing every click — voice and screen are fine, but the cursor never lands anywhere. Chrome sessions look perfect. Looping in Tomas, who set up the embed.', '{}', '<e_0516@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1099479), (CAST(strftime('%s','now') AS INTEGER) - 1099479), '[{"email":"tomas.reiner@pixelcraft.studio","name":"Tomas Reiner"},{"email":"fiona.boyle@pixelcraft.studio","name":"Fiona Boyle"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9'),
  ('e_0517', 'p_g01', 'support@givefeedback.dev', 'Re: Clicks not captured in Safari replays', '<p>Embed is the standard one-line tag in our root layout, nothing custom. It reproduces on Safari 17.0 and 17.1, both desktop and iPad. Happy to share a session ID.</p>', 'Embed is the standard one-line tag in our root layout, nothing custom. It reproduces on Safari 17.0 and 17.1, both desktop and iPad. Happy to share a session ID.', '{}', '<e_0517@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1072167), (CAST(strftime('%s','now') AS INTEGER) - 1072167), '[{"email":"elena.varga@pixelcraft.studio","name":"Elena Varga"},{"email":"fiona.boyle@pixelcraft.studio","name":"Fiona Boyle"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9'),
  ('e_0518', 'p_g01', 'support@givefeedback.dev', 'Re: Clicks not captured in Safari replays', '<p>Directly on the page for production, but our client reviews inside a staging preview that is iframed. That would explain why our own tests passed.</p>', 'Directly on the page for production, but our client reviews inside a staging preview that is iframed. That would explain why our own tests passed.', '{}', '<e_0518@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1029345), (CAST(strftime('%s','now') AS INTEGER) - 1029345), '[{"email":"elena.varga@pixelcraft.studio","name":"Elena Varga"},{"email":"fiona.boyle@pixelcraft.studio","name":"Fiona Boyle"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9'),
  ('e_0519', 'p_g02', 'support@givefeedback.dev', 'Re: Clicks not captured in Safari replays', '<p>Hi all — Fiona from the design side, just looped in. Once this is fixed, will the older sessions that missed clicks get them back, or only new recordings?</p>', 'Hi all — Fiona from the design side, just looped in. Once this is fixed, will the older sessions that missed clicks get them back, or only new recordings?', '{}', '<e_0519@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 812694), (CAST(strftime('%s','now') AS INTEGER) - 812694), '[{"email":"elena.varga@pixelcraft.studio","name":"Elena Varga"},{"email":"tomas.reiner@pixelcraft.studio","name":"Tomas Reiner"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9');

INSERT OR REPLACE INTO emails (id, person_id, recipient, subject, body_html, body_text, raw_headers, message_id, spf, dkim, dmarc, is_read, received_at, created_at, cc, conversation_id) VALUES
  ('e_0520', 'p_g00', 'support@givefeedback.dev', 'Re: Clicks not captured in Safari replays', '<p>Confirmed the new release captures clicks in the iframe''d preview now. Thanks for the quick turnaround — closing this on our side.</p>', 'Confirmed the new release captures clicks in the iframe''d preview now. Thanks for the quick turnaround — closing this on our side.', '{}', '<e_0520@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 620394), (CAST(strftime('%s','now') AS INTEGER) - 620394), '[{"email":"tomas.reiner@pixelcraft.studio","name":"Tomas Reiner"},{"email":"fiona.boyle@pixelcraft.studio","name":"Fiona Boyle"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9'),
  ('e_0521', 'p_g03', 'mahmoud@givefeedback.dev', 'Rolling GiveFeedback out across our client sites', '<p>We run about 30 active client sites and want GiveFeedback on all of them. Two questions before we commit: is pricing per-project or per-seat, and can the widget be lightly white-labeled so it reads as ours to the client? Darius runs our ops.</p>', 'We run about 30 active client sites and want GiveFeedback on all of them. Two questions before we commit: is pricing per-project or per-seat, and can the widget be lightly white-labeled so it reads as ours to the client? Darius runs our ops.', '{}', '<e_0521@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1289613), (CAST(strftime('%s','now') AS INTEGER) - 1289613), '[{"email":"darius.weiss@northlight.agency","name":"Darius Weiss"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_52fc1e52f07c3e90'),
  ('e_0522', 'p_g04', 'mahmoud@givefeedback.dev', 'Re: Rolling GiveFeedback out across our client sites', '<p>Ops question: when we hand a project off to a client at the end of an engagement, can we transfer ownership without losing the session history?</p>', 'Ops question: when we hand a project off to a client at the end of an engagement, can we transfer ownership without losing the session history?', '{}', '<e_0522@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1128497), (CAST(strftime('%s','now') AS INTEGER) - 1128497), '[{"email":"harriet.cole@northlight.agency","name":"Harriet Cole"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_52fc1e52f07c3e90'),
  ('e_0523', 'p_g03', 'mahmoud@givefeedback.dev', 'Re: Rolling GiveFeedback out across our client sites', '<p>That''s exactly what we needed. Adding Darius to finalize — he''ll set up the billing and the first ten projects this week.</p>', 'That''s exactly what we needed. Adding Darius to finalize — he''ll set up the billing and the first ten projects this week.', '{}', '<e_0523@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 979384), (CAST(strftime('%s','now') AS INTEGER) - 979384), '[{"email":"darius.weiss@northlight.agency","name":"Darius Weiss"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_52fc1e52f07c3e90'),
  ('e_0524', 'p_g04', 'mahmoud@givefeedback.dev', 'Re: Rolling GiveFeedback out across our client sites', '<p>First ten projects are live and the logo swap looks clean. We''ll bring the rest over next sprint.</p>', 'First ten projects are live and the logo swap looks clean. We''ll bring the rest over next sprint.', '{}', '<e_0524@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 744982), (CAST(strftime('%s','now') AS INTEGER) - 744982), '[{"email":"harriet.cole@northlight.agency","name":"Harriet Cole"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_52fc1e52f07c3e90'),
  ('e_0525', 'p_g05', 'support@givefeedback.dev', 'Push extracted tasks into Linear', '<p>The task extraction is genuinely great, but copy-pasting each one into Linear is where we lose the time we just saved. Any way to push a session''s tasks straight into a Linear team? Sienna and Noor from engineering are CC''d.</p>', 'The task extraction is genuinely great, but copy-pasting each one into Linear is where we lose the time we just saved. Any way to push a session''s tasks straight into a Linear team? Sienna and Noor from engineering are CC''d.', '{}', '<e_0525@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1640282), (CAST(strftime('%s','now') AS INTEGER) - 1640282), '[{"email":"sienna.holt@tandemlabs.io","name":"Sienna Holt"},{"email":"noor.haddad@tandemlabs.io","name":"Noor Haddad"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('e_0526', 'p_g06', 'support@givefeedback.dev', 'Re: Push extracted tasks into Linear', '<p>Effort estimate mapped to Linear''s estimate points would be huge, and the replay link in the description is a must. If you can set the team and a default label, that covers 90% of our flow.</p>', 'Effort estimate mapped to Linear''s estimate points would be huge, and the replay link in the description is a must. If you can set the team and a default label, that covers 90% of our flow.', '{}', '<e_0526@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1542763), (CAST(strftime('%s','now') AS INTEGER) - 1542763), '[{"email":"rajiv.kapur@tandemlabs.io","name":"Rajiv Kapur"},{"email":"noor.haddad@tandemlabs.io","name":"Noor Haddad"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('e_0527', 'p_g07', 'support@givefeedback.dev', 'Re: Push extracted tasks into Linear', '<p>Noor here, I own our Linear workspace. Will this use a personal API token or a proper OAuth app? Security won''t approve a shared personal token.</p>', 'Noor here, I own our Linear workspace. Will this use a personal API token or a proper OAuth app? Security won''t approve a shared personal token.', '{}', '<e_0527@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1426998), (CAST(strftime('%s','now') AS INTEGER) - 1426998), '[{"email":"rajiv.kapur@tandemlabs.io","name":"Rajiv Kapur"},{"email":"sienna.holt@tandemlabs.io","name":"Sienna Holt"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('e_0528', 'p_g05', 'support@givefeedback.dev', 'Re: Push extracted tasks into Linear', '<p>That clears it with our security team. Sign us up for early access.</p>', 'That clears it with our security team. Sign us up for early access.', '{}', '<e_0528@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1131121), (CAST(strftime('%s','now') AS INTEGER) - 1131121), '[{"email":"sienna.holt@tandemlabs.io","name":"Sienna Holt"},{"email":"noor.haddad@tandemlabs.io","name":"Noor Haddad"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('e_0529', 'p_g08', 'mahmoud@givefeedback.dev', 'Webflow marketplace integration', '<p>We ship a couple of Webflow apps and think GiveFeedback would be a natural marketplace listing — one-click install of the widget on any Webflow site. Would you be open to co-building it? Kenji is our lead dev on the Webflow side.</p>', 'We ship a couple of Webflow apps and think GiveFeedback would be a natural marketplace listing — one-click install of the widget on any Webflow site. Would you be open to co-building it? Kenji is our lead dev on the Webflow side.', '{}', '<e_0529@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1642059), (CAST(strftime('%s','now') AS INTEGER) - 1642059), '[{"email":"kenji.yamada@driftwood.agency","name":"Kenji Yamada"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_532e30d55ede6ec9'),
  ('e_0530', 'p_g09', 'mahmoud@givefeedback.dev', 'Re: Webflow marketplace integration', '<p>Site-settings injection is the clean path: we drop the widget script into the custom-code head field and pass the project key. No per-page work for the user. We''d need a stable embed URL and a way to mint project keys via API.</p>', 'Site-settings injection is the clean path: we drop the widget script into the custom-code head field and pass the project key. No per-page work for the user. We''d need a stable embed URL and a way to mint project keys via API.', '{}', '<e_0530@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1564985), (CAST(strftime('%s','now') AS INTEGER) - 1564985), '[{"email":"priya.singh@driftwood.agency","name":"Priya Singh"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_532e30d55ede6ec9'),
  ('e_0531', 'p_g08', 'mahmoud@givefeedback.dev', 'Re: Webflow marketplace integration', '<p>Yes — Tuesday or Wednesday works. If v1 lands well, we''d feature it in our next Webflow newsletter (~9k designers).</p>', 'Yes — Tuesday or Wednesday works. If v1 lands well, we''d feature it in our next Webflow newsletter (~9k designers).', '{}', '<e_0531@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1391042), (CAST(strftime('%s','now') AS INTEGER) - 1391042), '[{"email":"kenji.yamada@driftwood.agency","name":"Kenji Yamada"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_532e30d55ede6ec9'),
  ('e_0532', 'p_g09', 'mahmoud@givefeedback.dev', 'Re: Webflow marketplace integration', '<p>Provisioning call works against the sandbox — got a project + key back on the first try. We''ll have a rough install flow to demo by Friday.</p>', 'Provisioning call works against the sandbox — got a project + key back on the first try. We''ll have a rough install flow to demo by Friday.', '{}', '<e_0532@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1187111), (CAST(strftime('%s','now') AS INTEGER) - 1187111), '[{"email":"priya.singh@driftwood.agency","name":"Priya Singh"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_532e30d55ede6ec9'),
  ('e_0533', 'p_g10', 'support@givefeedback.dev', 'Recordings cut off at three minutes', '<p>Our client''s longer walkthroughs keep getting truncated around the three-minute mark — the transcript stops mid-sentence and the replay ends. It''s happened on our two most active projects this week. We''re losing the most detailed feedback.</p>', 'Our client''s longer walkthroughs keep getting truncated around the three-minute mark — the transcript stops mid-sentence and the replay ends. It''s happened on our two most active projects this week. We''re losing the most detailed feedback.', '{}', '<e_0533@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 457761), (CAST(strftime('%s','now') AS INTEGER) - 457761), '[{"email":"irina.popov@cascadeapp.co","name":"Irina Popov"},{"email":"mateo.santos@cascadeapp.co","name":"Mateo Santos"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', 'c_90cb738104b5a094'),
  ('e_0534', 'p_g11', 'support@givefeedback.dev', 'Re: Recordings cut off at three minutes', '<p>Thanks. Adding Mateo, who manages the projects — he''ll confirm once the longer recordings come through.</p>', 'Thanks. Adding Mateo, who manages the projects — he''ll confirm once the longer recordings come through.', '{}', '<e_0534@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 458971), (CAST(strftime('%s','now') AS INTEGER) - 458971), '[{"email":"alec.briggs@cascadeapp.co","name":"Alec Briggs"},{"email":"mateo.santos@cascadeapp.co","name":"Mateo Santos"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', 'c_90cb738104b5a094'),
  ('e_0535', 'p_g12', 'support@givefeedback.dev', 'Re: Recordings cut off at three minutes', '<p>Confirmed — just captured a nine-minute session end to end, transcript and replay both complete. One follow-up: how long are replays retained before the links expire?</p>', 'Confirmed — just captured a nine-minute session end to end, transcript and replay both complete. One follow-up: how long are replays retained before the links expire?', '{}', '<e_0535@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 420682), (CAST(strftime('%s','now') AS INTEGER) - 420682), '[{"email":"alec.briggs@cascadeapp.co","name":"Alec Briggs"},{"email":"irina.popov@cascadeapp.co","name":"Irina Popov"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', 'c_90cb738104b5a094'),
  ('e_0536', 'p_g10', 'support@givefeedback.dev', 'Re: Recordings cut off at three minutes', '<p>That works for us. Appreciate the fast fix — resolved on our end.</p>', 'That works for us. Appreciate the fast fix — resolved on our end.', '{}', '<e_0536@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 176842), (CAST(strftime('%s','now') AS INTEGER) - 176842), '[{"email":"irina.popov@cascadeapp.co","name":"Irina Popov"},{"email":"mateo.santos@cascadeapp.co","name":"Mateo Santos"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', 'c_90cb738104b5a094'),
  ('e_0537', 'p_g13', 'support@givefeedback.dev', 'Getting the widget onto all our client sites', '<p>Just signed up and excited to roll this out. We build in a mix of Next.js and Webflow. Looping in Ravi (engineering) and Lucia (client ops) so we can get the widget live everywhere this week.</p>', 'Just signed up and excited to roll this out. We build in a mix of Next.js and Webflow. Looping in Ravi (engineering) and Lucia (client ops) so we can get the widget live everywhere this week.', '{}', '<e_0537@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1032156), (CAST(strftime('%s','now') AS INTEGER) - 1032156), '[{"email":"ravi.menon@meridian.studio","name":"Ravi Menon"},{"email":"lucia.fernandez@meridian.studio","name":"Lucia Fernandez"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_af2308ac2d70cc79'),
  ('e_0538', 'p_g14', 'support@givefeedback.dev', 'Re: Getting the widget onto all our client sites', '<p>For the Next.js App Router — root layout as a normal script tag, or do we need the next/script component with a strategy?</p>', 'For the Next.js App Router — root layout as a normal script tag, or do we need the next/script component with a strategy?', '{}', '<e_0538@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 870759), (CAST(strftime('%s','now') AS INTEGER) - 870759), '[{"email":"jana.kowalski@meridian.studio","name":"Jana Kowalski"},{"email":"lucia.fernandez@meridian.studio","name":"Lucia Fernandez"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_af2308ac2d70cc79'),
  ('e_0539', 'p_g15', 'support@givefeedback.dev', 'Re: Getting the widget onto all our client sites', '<p>Client-ops side: we want clients leaving feedback but not poking around the dashboard. What''s the cleanest way to bring a client in?</p>', 'Client-ops side: we want clients leaving feedback but not poking around the dashboard. What''s the cleanest way to bring a client in?', '{}', '<e_0539@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 829569), (CAST(strftime('%s','now') AS INTEGER) - 829569), '[{"email":"jana.kowalski@meridian.studio","name":"Jana Kowalski"},{"email":"ravi.menon@meridian.studio","name":"Ravi Menon"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_af2308ac2d70cc79');

INSERT OR REPLACE INTO emails (id, person_id, recipient, subject, body_html, body_text, raw_headers, message_id, spf, dkim, dmarc, is_read, received_at, created_at, cc, conversation_id) VALUES
  ('e_0540', 'p_g13', 'support@givefeedback.dev', 'Re: Getting the widget onto all our client sites', '<p>That''s simpler than we expected. First three sites are live and recording. Thanks for the hand-holding.</p>', 'That''s simpler than we expected. First three sites are live and recording. Thanks for the hand-holding.', '{}', '<e_0540@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 722346), (CAST(strftime('%s','now') AS INTEGER) - 722346), '[{"email":"ravi.menon@meridian.studio","name":"Ravi Menon"},{"email":"lucia.fernandez@meridian.studio","name":"Lucia Fernandez"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_af2308ac2d70cc79'),
  ('e_0541', 'p_g16', 'support@givefeedback.dev', 'Tuning task extraction for our sessions', '<p>We''ve run about 40 sessions and the task extraction is strong, but it under-splits: when a client asks for three related changes in one breath, it often lands as a single task. We''d rather have three granular tasks. Sharing team feedback below.</p>', 'We''ve run about 40 sessions and the task extraction is strong, but it under-splits: when a client asks for three related changes in one breath, it often lands as a single task. We''d rather have three granular tasks. Sharing team feedback below.', '{}', '<e_0541@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1389785), (CAST(strftime('%s','now') AS INTEGER) - 1389785), '[{"email":"hugo.lefevre@oakhouse.design","name":"Hugo Lefevre"},{"email":"anika.osei@oakhouse.design","name":"Anika Osei"},{"email":"petr.zelinka@oakhouse.design","name":"Petr Zelinka"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('e_0542', 'p_g17', 'support@givefeedback.dev', 'Re: Tuning task extraction for our sessions', '<p>Adding to that — it sometimes turns a passing comment ("oh and I like this color") into a task. A little more precision on what counts as a request would cut the noise.</p>', 'Adding to that — it sometimes turns a passing comment ("oh and I like this color") into a task. A little more precision on what counts as a request would cut the noise.', '{}', '<e_0542@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1462125), (CAST(strftime('%s','now') AS INTEGER) - 1462125), '[{"email":"deepa.rao@oakhouse.design","name":"Deepa Rao"},{"email":"anika.osei@oakhouse.design","name":"Anika Osei"},{"email":"petr.zelinka@oakhouse.design","name":"Petr Zelinka"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('e_0543', 'p_g18', 'support@givefeedback.dev', 'Re: Tuning task extraction for our sessions', '<p>Anika, design lead — yes please. Can we re-run extraction on an existing session without losing the tasks we''ve already triaged?</p>', 'Anika, design lead — yes please. Can we re-run extraction on an existing session without losing the tasks we''ve already triaged?', '{}', '<e_0543@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1373232), (CAST(strftime('%s','now') AS INTEGER) - 1373232), '[{"email":"deepa.rao@oakhouse.design","name":"Deepa Rao"},{"email":"hugo.lefevre@oakhouse.design","name":"Hugo Lefevre"},{"email":"petr.zelinka@oakhouse.design","name":"Petr Zelinka"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('e_0544', 'p_g19', 'support@givefeedback.dev', 'Re: Tuning task extraction for our sessions', '<p>Petr from engineering — when the granularity setting ships, can it be set via API? We provision projects programmatically and don''t want to click through each one.</p>', 'Petr from engineering — when the granularity setting ships, can it be set via API? We provision projects programmatically and don''t want to click through each one.', '{}', '<e_0544@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1184751), (CAST(strftime('%s','now') AS INTEGER) - 1184751), '[{"email":"deepa.rao@oakhouse.design","name":"Deepa Rao"},{"email":"hugo.lefevre@oakhouse.design","name":"Hugo Lefevre"},{"email":"anika.osei@oakhouse.design","name":"Anika Osei"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('e_0545', 'p_g16', 'support@givefeedback.dev', 'Re: Tuning task extraction for our sessions', '<p>Re-ran three sessions and the granular split is exactly right. The noise from affirmations is gone too. Great work — we''ll keep sending notes as we scale up.</p>', 'Re-ran three sessions and the granular split is exactly right. The noise from affirmations is gone too. Great work — we''ll keep sending notes as we scale up.', '{}', '<e_0545@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 802128), (CAST(strftime('%s','now') AS INTEGER) - 802128), '[{"email":"hugo.lefevre@oakhouse.design","name":"Hugo Lefevre"},{"email":"anika.osei@oakhouse.design","name":"Anika Osei"},{"email":"petr.zelinka@oakhouse.design","name":"Petr Zelinka"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('e_0546', 'p_g20', 'mahmoud@givefeedback.dev', 'Reseller terms for our retainer clients', '<p>We bundle a fixed toolset into every monthly retainer and want GiveFeedback in it. Looking for reseller terms — we''d own the client relationship and billing. Olu handles our tooling; Tariq at a partner studio is evaluating alongside us.</p>', 'We bundle a fixed toolset into every monthly retainer and want GiveFeedback in it. Looking for reseller terms — we''d own the client relationship and billing. Olu handles our tooling; Tariq at a partner studio is evaluating alongside us.', '{}', '<e_0546@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1828299), (CAST(strftime('%s','now') AS INTEGER) - 1828299), '[{"email":"olu.adebayo@makersyard.com","name":"Olu Adebayo"},{"email":"tariq.khan@oakhouse.design","name":"Tariq Khan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa'),
  ('e_0547', 'p_g21', 'mahmoud@givefeedback.dev', 'Re: Reseller terms for our retainer clients', '<p>Wholesale, so it''s invisible in the retainer. Two things matter: a single monthly invoice across all client projects, and being able to add or remove projects mid-month without a support ticket each time.</p>', 'Wholesale, so it''s invisible in the retainer. Two things matter: a single monthly invoice across all client projects, and being able to add or remove projects mid-month without a support ticket each time.', '{}', '<e_0547@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1745166), (CAST(strftime('%s','now') AS INTEGER) - 1745166), '[{"email":"priya.rendon@makersyard.com","name":"Priya Rendon"},{"email":"tariq.khan@oakhouse.design","name":"Tariq Khan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa'),
  ('e_0548', 'p_g22', 'mahmoud@givefeedback.dev', 'Re: Reseller terms for our retainer clients', '<p>Tariq here. If our studio joins the same reseller account later, can our projects be kept separate for our own client reporting?</p>', 'Tariq here. If our studio joins the same reseller account later, can our projects be kept separate for our own client reporting?', '{}', '<e_0548@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1714425), (CAST(strftime('%s','now') AS INTEGER) - 1714425), '[{"email":"priya.rendon@makersyard.com","name":"Priya Rendon"},{"email":"olu.adebayo@makersyard.com","name":"Olu Adebayo"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa'),
  ('e_0549', 'p_g20', 'mahmoud@givefeedback.dev', 'Re: Reseller terms for our retainer clients', '<p>Rate card looks good. We''ll start with eight projects this month and grow from there. Sending the signed reseller agreement today.</p>', 'Rate card looks good. We''ll start with eight projects this month and grow from there. Sending the signed reseller agreement today.', '{}', '<e_0549@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1244248), (CAST(strftime('%s','now') AS INTEGER) - 1244248), '[{"email":"olu.adebayo@makersyard.com","name":"Olu Adebayo"},{"email":"tariq.khan@oakhouse.design","name":"Tariq Khan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa'),
  ('e_0550', 'p_g23', 'mahmoud@givefeedback.dev', 'Joint webinar — feedback ops for agencies', '<p>Floating a co-marketing idea: a joint webinar on ''cutting client feedback rounds from days to hours'' — us, GiveFeedback, and Soren''s studio sharing real workflows. Soren''s interested and CC''d.</p>', 'Floating a co-marketing idea: a joint webinar on ''cutting client feedback rounds from days to hours'' — us, GiveFeedback, and Soren''s studio sharing real workflows. Soren''s interested and CC''d.', '{}', '<e_0550@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1723073), (CAST(strftime('%s','now') AS INTEGER) - 1723073), '[{"email":"soren.bakke@forgeworks.dev","name":"Soren Bakke"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_7e1ae34169e3f952'),
  ('e_0551', 'p_g24', 'mahmoud@givefeedback.dev', 'Re: Joint webinar — feedback ops for agencies', '<p>We''re in if it''s a panel with live audience Q&A rather than alternating slide decks — easier to keep candid and easier to recruit speakers for.</p>', 'We''re in if it''s a panel with live audience Q&A rather than alternating slide decks — easier to keep candid and easier to recruit speakers for.', '{}', '<e_0551@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1619000), (CAST(strftime('%s','now') AS INTEGER) - 1619000), '[{"email":"wren.callahan@tandemlabs.io","name":"Wren Callahan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_7e1ae34169e3f952'),
  ('e_0552', 'p_g23', 'mahmoud@givefeedback.dev', 'Re: Joint webinar — feedback ops for agencies', '<p>Mid-November works. Wren can moderate — I''ve MC''d a few of these and it frees the company panelists to be candid.</p>', 'Mid-November works. Wren can moderate — I''ve MC''d a few of these and it frees the company panelists to be candid.', '{}', '<e_0552@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1542456), (CAST(strftime('%s','now') AS INTEGER) - 1542456), '[{"email":"soren.bakke@forgeworks.dev","name":"Soren Bakke"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_7e1ae34169e3f952'),
  ('e_0553', 'p_g24', 'mahmoud@givefeedback.dev', 'Re: Joint webinar — feedback ops for agencies', '<p>We''ll promote it to our list (~11k designers and agency owners). Unified landing page is fine as long as we each get our UTM.</p>', 'We''ll promote it to our list (~11k designers and agency owners). Unified landing page is fine as long as we each get our UTM.', '{}', '<e_0553@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 1299554), (CAST(strftime('%s','now') AS INTEGER) - 1299554), '[{"email":"wren.callahan@tandemlabs.io","name":"Wren Callahan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_7e1ae34169e3f952'),
  ('e_0554', 'p_g25', 'projects@givefeedback.dev', 'Feedback rolling in on the Harbor redesign', '<p>The Harbor redesign project got six new sessions overnight after we sent the client the staging link. Bo, can you extract tasks from the last three? I''ll take the first three. Also flagging a question for GiveFeedback below.</p>', 'The Harbor redesign project got six new sessions overnight after we sent the client the staging link. Bo, can you extract tasks from the last three? I''ll take the first three. Also flagging a question for GiveFeedback below.', '{}', '<e_0554@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 702860), (CAST(strftime('%s','now') AS INTEGER) - 702860), '[{"email":"bo.westwood@loomandlens.com","name":"Bo Westwood"},{"email":"clara.jung@loomandlens.com","name":"Clara Jung"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_76f85f5b158aa224'),
  ('e_0555', 'p_g26', 'projects@givefeedback.dev', 'Re: Feedback rolling in on the Harbor redesign', '<p>On it. Two of mine had the client jumping between pages mid-sentence — the replay timeline makes it easy to follow, but is there a way to jump the transcript to a specific click?</p>', 'On it. Two of mine had the client jumping between pages mid-sentence — the replay timeline makes it easy to follow, but is there a way to jump the transcript to a specific click?', '{}', '<e_0555@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 762209), (CAST(strftime('%s','now') AS INTEGER) - 762209), '[{"email":"yuki.sato@loomandlens.com","name":"Yuki Sato"},{"email":"clara.jung@loomandlens.com","name":"Clara Jung"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_76f85f5b158aa224'),
  ('e_0556', 'p_g27', 'projects@givefeedback.dev', 'Re: Feedback rolling in on the Harbor redesign', '<p>Clara from the client-facing side, just joining. When we mark tasks done, does the client see status if we''ve shared the session link with them?</p>', 'Clara from the client-facing side, just joining. When we mark tasks done, does the client see status if we''ve shared the session link with them?', '{}', '<e_0556@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 612398), (CAST(strftime('%s','now') AS INTEGER) - 612398), '[{"email":"yuki.sato@loomandlens.com","name":"Yuki Sato"},{"email":"bo.westwood@loomandlens.com","name":"Bo Westwood"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_76f85f5b158aa224'),
  ('e_0557', 'p_g25', 'projects@givefeedback.dev', 'Re: Feedback rolling in on the Harbor redesign', '<p>All six sessions are triaged and the tasks are in our sprint. The timeline-scrub tip saved us a ton of time — thanks. Muting this thread now that we''re rolling.</p>', 'All six sessions are triaged and the tasks are in our sprint. The timeline-scrub tip saved us a ton of time — thanks. Muting this thread now that we''re rolling.', '{}', '<e_0557@givefeedback.dev>', 'pass', 'pass', 'pass', 1, (CAST(strftime('%s','now') AS INTEGER) - 475347), (CAST(strftime('%s','now') AS INTEGER) - 475347), '[{"email":"bo.westwood@loomandlens.com","name":"Bo Westwood"},{"email":"clara.jung@loomandlens.com","name":"Clara Jung"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_76f85f5b158aa224');

