  ('s_0036', 'p_g01', 'tomas.reiner@pixelcraft.studio', 'support@givefeedback.dev', 'Re: Clicks not captured in Safari replays', '<p>Thanks both — this looks like Safari dropping pointer events when the recorder runs inside a cross-origin iframe. Pulling a fix now. Quick check: is the widget embedded directly on the page, or inside an iframe''d preview?</p>', 'Thanks both — this looks like Safari dropping pointer events when the recorder runs inside a cross-origin iframe. Pulling a fix now. Quick check: is the widget embedded directly on the page, or inside an iframe''d preview?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 963655), (CAST(strftime('%s','now') AS INTEGER) - 963655), '[{"email":"elena.varga@pixelcraft.studio","name":"Elena Varga"},{"email":"fiona.boyle@pixelcraft.studio","name":"Fiona Boyle"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9'),
  ('s_0037', 'p_g01', 'tomas.reiner@pixelcraft.studio', 'support@givefeedback.dev', 'Re: Clicks not captured in Safari replays', '<p>That''s the one. We''re shipping a patch that captures pointer events on the parent frame for Safari. Should land in tomorrow''s widget release — no code change needed on your end, just a hard refresh.</p>', 'That''s the one. We''re shipping a patch that captures pointer events on the parent frame for Safari. Should land in tomorrow''s widget release — no code change needed on your end, just a hard refresh.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 831245), (CAST(strftime('%s','now') AS INTEGER) - 831245), '[{"email":"elena.varga@pixelcraft.studio","name":"Elena Varga"},{"email":"fiona.boyle@pixelcraft.studio","name":"Fiona Boyle"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9'),
  ('s_0038', 'p_g02', 'fiona.boyle@pixelcraft.studio', 'support@givefeedback.dev', 'Re: Clicks not captured in Safari replays', '<p>Only new recordings, unfortunately — the click data was never captured for the old ones. Everything from the patched release forward will be complete.</p>', 'Only new recordings, unfortunately — the click data was never captured for the old ones. Everything from the patched release forward will be complete.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 736176), (CAST(strftime('%s','now') AS INTEGER) - 736176), '[{"email":"elena.varga@pixelcraft.studio","name":"Elena Varga"},{"email":"tomas.reiner@pixelcraft.studio","name":"Tomas Reiner"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_3f73f9a52b73c0b9'),
  ('s_0039', 'p_g03', 'harriet.cole@northlight.agency', 'mahmoud@givefeedback.dev', 'Re: Rolling GiveFeedback out across our client sites', '<p>Great to hear it, Harriet. Pricing is per-project with unlimited viewers, so 30 sites is 30 projects regardless of how many of your people log in. White-label (your logo + accent on the widget) is on the Studio plan.</p>', 'Great to hear it, Harriet. Pricing is per-project with unlimited viewers, so 30 sites is 30 projects regardless of how many of your people log in. White-label (your logo + accent on the widget) is on the Studio plan.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1217974), (CAST(strftime('%s','now') AS INTEGER) - 1217974), '[{"email":"darius.weiss@northlight.agency","name":"Darius Weiss"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_52fc1e52f07c3e90');

INSERT OR REPLACE INTO sent_emails (id, person_id, to_address, from_address, subject, body_html, body_text, in_reply_to, status, sent_at, created_at, cc, conversation_id) VALUES
  ('s_0040', 'p_g04', 'darius.weiss@northlight.agency', 'mahmoud@givefeedback.dev', 'Re: Rolling GiveFeedback out across our client sites', '<p>Yes — projects can be transferred to another account and the full session + task history goes with them. We can also keep a read-only archive on your side if you want continuity.</p>', 'Yes — projects can be transferred to another account and the full session + task history goes with them. We can also keep a read-only archive on your side if you want continuity.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1196779), (CAST(strftime('%s','now') AS INTEGER) - 1196779), '[{"email":"harriet.cole@northlight.agency","name":"Harriet Cole"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_52fc1e52f07c3e90'),
  ('s_0041', 'p_g03', 'harriet.cole@northlight.agency', 'mahmoud@givefeedback.dev', 'Re: Rolling GiveFeedback out across our client sites', '<p>Perfect. I''ll send the Studio plan link and a short white-label setup guide. Ping me directly if anything''s unclear during the first rollout.</p>', 'Perfect. I''ll send the Studio plan link and a short white-label setup guide. Ping me directly if anything''s unclear during the first rollout.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 980706), (CAST(strftime('%s','now') AS INTEGER) - 980706), '[{"email":"darius.weiss@northlight.agency","name":"Darius Weiss"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_52fc1e52f07c3e90'),
  ('s_0042', 'p_g05', 'rajiv.kapur@tandemlabs.io', 'support@givefeedback.dev', 'Re: Push extracted tasks into Linear', '<p>This is our most-requested integration and it''s in build now. First version maps each extracted task to a Linear issue with the replay link, timestamp, and effort estimate in the description. Which fields matter most for your triage?</p>', 'This is our most-requested integration and it''s in build now. First version maps each extracted task to a Linear issue with the replay link, timestamp, and effort estimate in the description. Which fields matter most for your triage?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1605447), (CAST(strftime('%s','now') AS INTEGER) - 1605447), '[{"email":"sienna.holt@tandemlabs.io","name":"Sienna Holt"},{"email":"noor.haddad@tandemlabs.io","name":"Noor Haddad"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('s_0043', 'p_g06', 'sienna.holt@tandemlabs.io', 'support@givefeedback.dev', 'Re: Push extracted tasks into Linear', '<p>All three are in scope: team + default label are configurable per project, and we''ll map effort to estimate points. Rolling out behind a flag next week — want early access?</p>', 'All three are in scope: team + default label are configurable per project, and we''ll map effort to estimate points. Rolling out behind a flag next week — want early access?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1548052), (CAST(strftime('%s','now') AS INTEGER) - 1548052), '[{"email":"rajiv.kapur@tandemlabs.io","name":"Rajiv Kapur"},{"email":"noor.haddad@tandemlabs.io","name":"Noor Haddad"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('s_0044', 'p_g07', 'noor.haddad@tandemlabs.io', 'support@givefeedback.dev', 'Re: Push extracted tasks into Linear', '<p>OAuth app — you''ll authorize GiveFeedback from Linear''s integrations page, no tokens to paste. Scoped to issue creation only.</p>', 'OAuth app — you''ll authorize GiveFeedback from Linear''s integrations page, no tokens to paste. Scoped to issue creation only.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1339288), (CAST(strftime('%s','now') AS INTEGER) - 1339288), '[{"email":"rajiv.kapur@tandemlabs.io","name":"Rajiv Kapur"},{"email":"sienna.holt@tandemlabs.io","name":"Sienna Holt"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('s_0045', 'p_g05', 'rajiv.kapur@tandemlabs.io', 'support@givefeedback.dev', 'Re: Push extracted tasks into Linear', '<p>You''re on the early-access list — the flag is live on your account now. Let us know how the first sync goes.</p>', 'You''re on the early-access list — the flag is live on your account now. Let us know how the first sync goes.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1075311), (CAST(strftime('%s','now') AS INTEGER) - 1075311), '[{"email":"sienna.holt@tandemlabs.io","name":"Sienna Holt"},{"email":"noor.haddad@tandemlabs.io","name":"Noor Haddad"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_a925b2f98d60f475'),
  ('s_0046', 'p_g08', 'priya.singh@driftwood.agency', 'mahmoud@givefeedback.dev', 'Re: Webflow marketplace integration', '<p>Love this. A Webflow one-click install would remove the only friction our agency users hit. What does the integration surface look like on your end — a designer extension, a site-settings injection, or both?</p>', 'Love this. A Webflow one-click install would remove the only friction our agency users hit. What does the integration surface look like on your end — a designer extension, a site-settings injection, or both?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1594267), (CAST(strftime('%s','now') AS INTEGER) - 1594267), '[{"email":"kenji.yamada@driftwood.agency","name":"Kenji Yamada"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_532e30d55ede6ec9'),
  ('s_0047', 'p_g09', 'kenji.yamada@driftwood.agency', 'mahmoud@givefeedback.dev', 'Re: Webflow marketplace integration', '<p>We can expose a project-provisioning endpoint for you so the app creates a project and returns the key in one call. Embed URL is already stable. Want to scope a v1 on a call next week?</p>', 'We can expose a project-provisioning endpoint for you so the app creates a project and returns the key in one call. Embed URL is already stable. Want to scope a v1 on a call next week?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1512284), (CAST(strftime('%s','now') AS INTEGER) - 1512284), '[{"email":"priya.singh@driftwood.agency","name":"Priya Singh"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_532e30d55ede6ec9'),
  ('s_0048', 'p_g08', 'priya.singh@driftwood.agency', 'mahmoud@givefeedback.dev', 'Re: Webflow marketplace integration', '<p>Wednesday it is. I''ll bring our API docs and a sandbox key so Kenji can start wiring the provisioning call the same day.</p>', 'Wednesday it is. I''ll bring our API docs and a sandbox key so Kenji can start wiring the provisioning call the same day.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1417063), (CAST(strftime('%s','now') AS INTEGER) - 1417063), '[{"email":"kenji.yamada@driftwood.agency","name":"Kenji Yamada"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_532e30d55ede6ec9'),
  ('s_0049', 'p_g10', 'alec.briggs@cascadeapp.co', 'support@givefeedback.dev', 'Re: Recordings cut off at three minutes', '<p>Sorry about that — three minutes is the default per-session cap on the Starter plan, and it should warn the recorder before it hits, not cut silently. Two things: we''re raising the cap to fifteen minutes on your plan today, and we''re fixing the missing warning.</p>', 'Sorry about that — three minutes is the default per-session cap on the Starter plan, and it should warn the recorder before it hits, not cut silently. Two things: we''re raising the cap to fifteen minutes on your plan today, and we''re fixing the missing warning.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 488003), (CAST(strftime('%s','now') AS INTEGER) - 488003), '[{"email":"irina.popov@cascadeapp.co","name":"Irina Popov"},{"email":"mateo.santos@cascadeapp.co","name":"Mateo Santos"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', 'c_90cb738104b5a094'),
  ('s_0050', 'p_g11', 'irina.popov@cascadeapp.co', 'support@givefeedback.dev', 'Re: Recordings cut off at three minutes', '<p>Cap is raised on your account now. The two truncated sessions can''t be recovered past the cut, but everything recorded from here will run the full length.</p>', 'Cap is raised on your account now. The two truncated sessions can''t be recovered past the cut, but everything recorded from here will run the full length.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 428802), (CAST(strftime('%s','now') AS INTEGER) - 428802), '[{"email":"alec.briggs@cascadeapp.co","name":"Alec Briggs"},{"email":"mateo.santos@cascadeapp.co","name":"Mateo Santos"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', 'c_90cb738104b5a094'),
  ('s_0051', 'p_g12', 'mateo.santos@cascadeapp.co', 'support@givefeedback.dev', 'Re: Recordings cut off at three minutes', '<p>Replays are kept for 90 days on your plan, and you can export any session''s video + tasks before then. We''re adding a per-project retention setting next month for teams that need longer.</p>', 'Replays are kept for 90 days on your plan, and you can export any session''s video + tasks before then. We''re adding a per-project retention setting next month for teams that need longer.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 312505), (CAST(strftime('%s','now') AS INTEGER) - 312505), '[{"email":"alec.briggs@cascadeapp.co","name":"Alec Briggs"},{"email":"irina.popov@cascadeapp.co","name":"Irina Popov"},{"email":"mahmoud@givefeedback.dev","name":"Mahmoud Halat"}]', 'c_90cb738104b5a094'),
  ('s_0052', 'p_g13', 'jana.kowalski@meridian.studio', 'support@givefeedback.dev', 'Re: Getting the widget onto all our client sites', '<p>Welcome aboard! Quick map: Next.js sites get the one-line script tag in the root layout; Webflow sites get it in the site-wide custom-code head field. One project per site keeps sessions cleanly separated. Happy to review your first install.</p>', 'Welcome aboard! Quick map: Next.js sites get the one-line script tag in the root layout; Webflow sites get it in the site-wide custom-code head field. One project per site keeps sessions cleanly separated. Happy to review your first install.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1030380), (CAST(strftime('%s','now') AS INTEGER) - 1030380), '[{"email":"ravi.menon@meridian.studio","name":"Ravi Menon"},{"email":"lucia.fernandez@meridian.studio","name":"Lucia Fernandez"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_af2308ac2d70cc79'),
  ('s_0053', 'p_g14', 'ravi.menon@meridian.studio', 'support@givefeedback.dev', 'Re: Getting the widget onto all our client sites', '<p>next/script with strategy="afterInteractive" in the root layout is ideal — it loads on every route without blocking render. Drop the project key as a data attribute and you''re set.</p>', 'next/script with strategy="afterInteractive" in the root layout is ideal — it loads on every route without blocking render. Drop the project key as a data attribute and you''re set.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 889558), (CAST(strftime('%s','now') AS INTEGER) - 889558), '[{"email":"jana.kowalski@meridian.studio","name":"Jana Kowalski"},{"email":"lucia.fernandez@meridian.studio","name":"Lucia Fernandez"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_af2308ac2d70cc79'),
  ('s_0054', 'p_g15', 'lucia.fernandez@meridian.studio', 'support@givefeedback.dev', 'Re: Getting the widget onto all our client sites', '<p>Clients don''t need an account at all — they just record on the site via the widget. For reviewing sessions, send them a per-session viewer link; it''s read-only and doesn''t consume a seat.</p>', 'Clients don''t need an account at all — they just record on the site via the widget. For reviewing sessions, send them a per-session viewer link; it''s read-only and doesn''t consume a seat.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 844491), (CAST(strftime('%s','now') AS INTEGER) - 844491), '[{"email":"jana.kowalski@meridian.studio","name":"Jana Kowalski"},{"email":"ravi.menon@meridian.studio","name":"Ravi Menon"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_af2308ac2d70cc79'),
  ('s_0055', 'p_g17', 'hugo.lefevre@oakhouse.design', 'support@givefeedback.dev', 'Re: Tuning task extraction for our sessions', '<p>Really useful — both are on our radar. Granularity: we''re adding a per-project setting for how aggressively to split multi-part requests. Precision: the next model pass ignores affirmations and only extracts actionable asks. Want to try the new extraction on a few past sessions?</p>', 'Really useful — both are on our radar. Granularity: we''re adding a per-project setting for how aggressively to split multi-part requests. Precision: the next model pass ignores affirmations and only extracts actionable asks. Want to try the new extraction on a few past sessions?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1334736), (CAST(strftime('%s','now') AS INTEGER) - 1334736), '[{"email":"deepa.rao@oakhouse.design","name":"Deepa Rao"},{"email":"anika.osei@oakhouse.design","name":"Anika Osei"},{"email":"petr.zelinka@oakhouse.design","name":"Petr Zelinka"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('s_0056', 'p_g18', 'anika.osei@oakhouse.design', 'support@givefeedback.dev', 'Re: Tuning task extraction for our sessions', '<p>Re-running creates a fresh task set side-by-side so your triaged ones stay put — you keep whichever you prefer. Turned it on for your account; try it on a session and tell us if the split feels right.</p>', 'Re-running creates a fresh task set side-by-side so your triaged ones stay put — you keep whichever you prefer. Turned it on for your account; try it on a session and tell us if the split feels right.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1240077), (CAST(strftime('%s','now') AS INTEGER) - 1240077), '[{"email":"deepa.rao@oakhouse.design","name":"Deepa Rao"},{"email":"hugo.lefevre@oakhouse.design","name":"Hugo Lefevre"},{"email":"petr.zelinka@oakhouse.design","name":"Petr Zelinka"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('s_0057', 'p_g19', 'petr.zelinka@oakhouse.design', 'support@givefeedback.dev', 'Re: Tuning task extraction for our sessions', '<p>Yes — it''ll be a field on the project-update endpoint, so you can set it at provision time. Shipping with the same release.</p>', 'Yes — it''ll be a field on the project-update endpoint, so you can set it at provision time. Shipping with the same release.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1125598), (CAST(strftime('%s','now') AS INTEGER) - 1125598), '[{"email":"deepa.rao@oakhouse.design","name":"Deepa Rao"},{"email":"hugo.lefevre@oakhouse.design","name":"Hugo Lefevre"},{"email":"anika.osei@oakhouse.design","name":"Anika Osei"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_b3336504783b6e93'),
  ('s_0058', 'p_g20', 'priya.rendon@makersyard.com', 'mahmoud@givefeedback.dev', 'Re: Reseller terms for our retainer clients', '<p>Happy to set this up. Reseller works two ways with us: you pay wholesale and bill your client directly, or we bill and pay you a referral share. For bundled retainers most agencies pick wholesale. What''s the deciding factor for you?</p>', 'Happy to set this up. Reseller works two ways with us: you pay wholesale and bill your client directly, or we bill and pay you a referral share. For bundled retainers most agencies pick wholesale. What''s the deciding factor for you?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1888949), (CAST(strftime('%s','now') AS INTEGER) - 1888949), '[{"email":"olu.adebayo@makersyard.com","name":"Olu Adebayo"},{"email":"tariq.khan@oakhouse.design","name":"Tariq Khan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa'),
  ('s_0059', 'p_g21', 'olu.adebayo@makersyard.com', 'mahmoud@givefeedback.dev', 'Re: Reseller terms for our retainer clients', '<p>Both supported — one consolidated monthly invoice, and project add/remove is self-serve from the reseller dashboard with proration. Sending the wholesale rate card now.</p>', 'Both supported — one consolidated monthly invoice, and project add/remove is self-serve from the reseller dashboard with proration. Sending the wholesale rate card now.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1747469), (CAST(strftime('%s','now') AS INTEGER) - 1747469), '[{"email":"priya.rendon@makersyard.com","name":"Priya Rendon"},{"email":"tariq.khan@oakhouse.design","name":"Tariq Khan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa');

INSERT OR REPLACE INTO sent_emails (id, person_id, to_address, from_address, subject, body_html, body_text, in_reply_to, status, sent_at, created_at, cc, conversation_id) VALUES
  ('s_0060', 'p_g22', 'tariq.khan@oakhouse.design', 'mahmoud@givefeedback.dev', 'Re: Reseller terms for our retainer clients', '<p>Yes — sub-accounts under one reseller keep projects and reporting separate while rolling up to a single invoice. That covers a multi-studio setup cleanly.</p>', 'Yes — sub-accounts under one reseller keep projects and reporting separate while rolling up to a single invoice. That covers a multi-studio setup cleanly.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1592559), (CAST(strftime('%s','now') AS INTEGER) - 1592559), '[{"email":"priya.rendon@makersyard.com","name":"Priya Rendon"},{"email":"olu.adebayo@makersyard.com","name":"Olu Adebayo"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa'),
  ('s_0061', 'p_g20', 'priya.rendon@makersyard.com', 'mahmoud@givefeedback.dev', 'Re: Reseller terms for our retainer clients', '<p>Received and countersigned — your reseller dashboard is provisioned. Add the eight projects whenever you''re ready.</p>', 'Received and countersigned — your reseller dashboard is provisioned. Add the eight projects whenever you''re ready.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1086824), (CAST(strftime('%s','now') AS INTEGER) - 1086824), '[{"email":"olu.adebayo@makersyard.com","name":"Olu Adebayo"},{"email":"tariq.khan@oakhouse.design","name":"Tariq Khan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"}]', 'c_0091cd163b79b2aa'),
  ('s_0062', 'p_g24', 'soren.bakke@forgeworks.dev', 'mahmoud@givefeedback.dev', 'Re: Joint webinar — feedback ops for agencies', '<p>Panel format is perfect. Proposal: four panelists (one per company plus a moderator), 30 min discussion, 20 min Q&A. We''ll bring anonymized before/after data on feedback-round times. Mid-November?</p>', 'Panel format is perfect. Proposal: four panelists (one per company plus a moderator), 30 min discussion, 20 min Q&A. We''ll bring anonymized before/after data on feedback-round times. Mid-November?', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1609132), (CAST(strftime('%s','now') AS INTEGER) - 1609132), '[{"email":"wren.callahan@tandemlabs.io","name":"Wren Callahan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_7e1ae34169e3f952'),
  ('s_0063', 'p_g23', 'wren.callahan@tandemlabs.io', 'mahmoud@givefeedback.dev', 'Re: Joint webinar — feedback ops for agencies', '<p>Sold. We''ll draft the run-of-show and stand up the registration page with all three logos and per-company UTM tags so everyone can track their own signups.</p>', 'Sold. We''ll draft the run-of-show and stand up the registration page with all three logos and per-company UTM tags so everyone can track their own signups.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1392978), (CAST(strftime('%s','now') AS INTEGER) - 1392978), '[{"email":"soren.bakke@forgeworks.dev","name":"Soren Bakke"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_7e1ae34169e3f952'),
  ('s_0064', 'p_g24', 'soren.bakke@forgeworks.dev', 'mahmoud@givefeedback.dev', 'Re: Joint webinar — feedback ops for agencies', '<p>Done — UTMs are set per company. Draft run-of-show is in your inbox for review. Looking forward to it.</p>', 'Done — UTMs are set per company. Draft run-of-show is in your inbox for review. Looking forward to it.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 1304936), (CAST(strftime('%s','now') AS INTEGER) - 1304936), '[{"email":"wren.callahan@tandemlabs.io","name":"Wren Callahan"},{"email":"nadia@givefeedback.dev","name":"Nadia Reyes"},{"email":"priya@givefeedback.dev","name":"Priya Iyer"}]', 'c_7e1ae34169e3f952'),
  ('s_0065', 'p_g26', 'bo.westwood@loomandlens.com', 'projects@givefeedback.dev', 'Re: Feedback rolling in on the Harbor redesign', '<p>Yes — clicking any event on the replay timeline scrubs both the video and the transcript to that moment. There''s also a keyboard step-through (left/right arrows) once a session is focused. That''s usually faster for click-heavy sessions.</p>', 'Yes — clicking any event on the replay timeline scrubs both the video and the transcript to that moment. There''s also a keyboard step-through (left/right arrows) once a session is focused. That''s usually faster for click-heavy sessions.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 676901), (CAST(strftime('%s','now') AS INTEGER) - 676901), '[{"email":"yuki.sato@loomandlens.com","name":"Yuki Sato"},{"email":"clara.jung@loomandlens.com","name":"Clara Jung"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_76f85f5b158aa224'),
  ('s_0066', 'p_g27', 'clara.jung@loomandlens.com', 'projects@givefeedback.dev', 'Re: Feedback rolling in on the Harbor redesign', '<p>The read-only viewer link shows the session and its extracted tasks but not your internal status changes — clients see the feedback, not your task board. If you want to share progress, the project summary export is the cleaner artifact.</p>', 'The read-only viewer link shows the session and its extracted tasks but not your internal status changes — clients see the feedback, not your task board. If you want to share progress, the project summary export is the cleaner artifact.', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 600398), (CAST(strftime('%s','now') AS INTEGER) - 600398), '[{"email":"yuki.sato@loomandlens.com","name":"Yuki Sato"},{"email":"bo.westwood@loomandlens.com","name":"Bo Westwood"},{"email":"owen@givefeedback.dev","name":"Owen Walsh"}]', 'c_76f85f5b158aa224'),
  ('st_000', 'p_013', 'diego.hassan@loomandlens.com', 'onboarding@givefeedback.dev', 'Welcome to GiveFeedback, Diego Hassan', '<span style="display:none;max-height:0;overflow:hidden;">Paste one script tag. Your clients record. AI extracts the tasks.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 40px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 18px 0;">Hey Diego Hassan,</p><p style="margin: 0 0 18px 0;">Thanks for signing up. I''m Mahmoud, the founder of GiveFeedback.</p><p style="margin: 0 0 18px 0;">I built this because I was tired of spending two hours every sprint translating vague client emails and Loom videos into dev tickets. Same scattered feedback on every project. So I built the tool I wished existed.</p><p style="margin: 0 0 18px 0;">Here''s how it works:</p><table style="margin: 0 0 24px 0; border-spacing: 0; border-collapse: collapse;"><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">1.</td><td style="padding: 8px 0;"><strong>Add the widget</strong><span style="color: rgba(10,10,10,0.6);"> - paste one script tag onto your site. Works with React, Next.js, WordPress, anything.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">2.</td><td style="padding: 8px 0;"><strong>Your client records feedback</strong><span style="color: rgba(10,10,10,0.6);"> - they talk and click right on your site. We capture voice, screen, and clicks together.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">3.</td><td style="padding: 8px 0;"><strong>Get dev-ready tasks</strong><span style="color: rgba(10,10,10,0.6);"> - AI turns their session into structured tasks with replays, timestamps, and effort estimates.</span></td></tr></table><p style="margin: 0 0 18px 0;">Early teams are cutting feedback rounds from 5 days down to a few hours. That''s the part I''m most proud of.</p><p style="margin: 0 0 6px 0; text-align: center; color: rgba(10,10,10,0.5); font-size: 13px;">Grab your embed code. Takes about 60 seconds.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Go to your dashboard →</a></p><p style="margin: 0 0 4px 0;">Mahmoud</p><p style="margin: 0; color: rgba(10,10,10,0.4); font-size: 13px;">Founder, givefeedback.dev · <a rel="noopener noreferrer" href="https://spaceandstory.co" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">spaceandstory.co</a></p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', '', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 3263834), (CAST(strftime('%s','now') AS INTEGER) - 3263834), NULL, NULL),
  ('st_001', 'p_013', 'diego.hassan@loomandlens.com', 'onboarding@givefeedback.dev', 'One tag away from your first session, Diego Hassan', '<span style="display:none;max-height:0;overflow:hidden;">Add the widget, send your client the link, watch the tasks appear.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 32px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 16px 0;">Hi Diego Hassan,</p><p style="margin: 0 0 18px 0;">You''re set up — here''s the fastest path to your first batch of dev-ready tasks:</p><table style="margin: 0 0 24px 0; border-spacing: 0; border-collapse: collapse;"><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">1.</td><td style="padding: 8px 0;"><strong>Paste your embed tag</strong><span style="color: rgba(10,10,10,0.6);"> - one line in your site''s &lt;head&gt;. It loads on every page automatically.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">2.</td><td style="padding: 8px 0;"><strong>Send your client the link</strong><span style="color: rgba(10,10,10,0.6);"> - they record right on the site. No login, no download.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">3.</td><td style="padding: 8px 0;"><strong>Open the session</strong><span style="color: rgba(10,10,10,0.6);"> - the AI has already turned it into tasks with replays and estimates.</span></td></tr></table><p style="margin: 0 0 18px 0;">Stuck on the install? Just reply — a real person (often me) reads every one.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Grab your embed code →</a></p><p style="margin: 0 0 4px 0;">Mahmoud</p><p style="margin: 0; color: rgba(10,10,10,0.4); font-size: 13px;">Founder, givefeedback.dev</p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', '', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 3091034), (CAST(strftime('%s','now') AS INTEGER) - 3091034), NULL, NULL),
  ('st_002', 'p_063', 'yara.singh@tandemlabs.io', 'onboarding@givefeedback.dev', 'Welcome to GiveFeedback, Yara Singh', '<span style="display:none;max-height:0;overflow:hidden;">Paste one script tag. Your clients record. AI extracts the tasks.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 40px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 18px 0;">Hey Yara Singh,</p><p style="margin: 0 0 18px 0;">Thanks for signing up. I''m Mahmoud, the founder of GiveFeedback.</p><p style="margin: 0 0 18px 0;">I built this because I was tired of spending two hours every sprint translating vague client emails and Loom videos into dev tickets. Same scattered feedback on every project. So I built the tool I wished existed.</p><p style="margin: 0 0 18px 0;">Here''s how it works:</p><table style="margin: 0 0 24px 0; border-spacing: 0; border-collapse: collapse;"><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">1.</td><td style="padding: 8px 0;"><strong>Add the widget</strong><span style="color: rgba(10,10,10,0.6);"> - paste one script tag onto your site. Works with React, Next.js, WordPress, anything.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">2.</td><td style="padding: 8px 0;"><strong>Your client records feedback</strong><span style="color: rgba(10,10,10,0.6);"> - they talk and click right on your site. We capture voice, screen, and clicks together.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">3.</td><td style="padding: 8px 0;"><strong>Get dev-ready tasks</strong><span style="color: rgba(10,10,10,0.6);"> - AI turns their session into structured tasks with replays, timestamps, and effort estimates.</span></td></tr></table><p style="margin: 0 0 18px 0;">Early teams are cutting feedback rounds from 5 days down to a few hours. That''s the part I''m most proud of.</p><p style="margin: 0 0 6px 0; text-align: center; color: rgba(10,10,10,0.5); font-size: 13px;">Grab your embed code. Takes about 60 seconds.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Go to your dashboard →</a></p><p style="margin: 0 0 4px 0;">Mahmoud</p><p style="margin: 0; color: rgba(10,10,10,0.4); font-size: 13px;">Founder, givefeedback.dev · <a rel="noopener noreferrer" href="https://spaceandstory.co" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">spaceandstory.co</a></p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', '', NULL, 'sent', (CAST(strftime('%s','now') AS INTEGER) - 4664224), (CAST(strftime('%s','now') AS INTEGER) - 4664224), NULL, NULL),
