INSERT OR REPLACE INTO email_templates (id, slug, name, subject, body_html, from_address, created_at, updated_at) VALUES
  ('tpl_00', 'signup-welcome', 'Onboarding · Welcome & first steps', 'Welcome to GiveFeedback, {{name}}', '<span style="display:none;max-height:0;overflow:hidden;">Paste one script tag. Your clients record. AI extracts the tasks.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 40px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 18px 0;">Hey {{name}},</p><p style="margin: 0 0 18px 0;">Thanks for signing up. I''m Mahmoud, the founder of GiveFeedback.</p><p style="margin: 0 0 18px 0;">I built this because I was tired of spending two hours every sprint translating vague client emails and Loom videos into dev tickets. Same scattered feedback on every project. So I built the tool I wished existed.</p><p style="margin: 0 0 18px 0;">Here''s how it works:</p><table style="margin: 0 0 24px 0; border-spacing: 0; border-collapse: collapse;"><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">1.</td><td style="padding: 8px 0;"><strong>Add the widget</strong><span style="color: rgba(10,10,10,0.6);"> - paste one script tag onto your site. Works with React, Next.js, WordPress, anything.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">2.</td><td style="padding: 8px 0;"><strong>Your client records feedback</strong><span style="color: rgba(10,10,10,0.6);"> - they talk and click right on your site. We capture voice, screen, and clicks together.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">3.</td><td style="padding: 8px 0;"><strong>Get dev-ready tasks</strong><span style="color: rgba(10,10,10,0.6);"> - AI turns their session into structured tasks with replays, timestamps, and effort estimates.</span></td></tr></table><p style="margin: 0 0 18px 0;">Early teams are cutting feedback rounds from 5 days down to a few hours. That''s the part I''m most proud of.</p><p style="margin: 0 0 6px 0; text-align: center; color: rgba(10,10,10,0.5); font-size: 13px;">Grab your embed code. Takes about 60 seconds.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Go to your dashboard →</a></p><p style="margin: 0 0 4px 0;">Mahmoud</p><p style="margin: 0; color: rgba(10,10,10,0.4); font-size: 13px;">Founder, givefeedback.dev · <a rel="noopener noreferrer" href="https://spaceandstory.co" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">spaceandstory.co</a></p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', 'onboarding@givefeedback.dev', CAST(strftime('%s','now') AS INTEGER), CAST(strftime('%s','now') AS INTEGER)),
  ('tpl_01', 'first-steps', 'Onboarding · Capture your first session', 'One tag away from your first session, {{name}}', '<span style="display:none;max-height:0;overflow:hidden;">Add the widget, send your client the link, watch the tasks appear.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 32px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 16px 0;">Hi {{name}},</p><p style="margin: 0 0 18px 0;">You''re set up — here''s the fastest path to your first batch of dev-ready tasks:</p><table style="margin: 0 0 24px 0; border-spacing: 0; border-collapse: collapse;"><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">1.</td><td style="padding: 8px 0;"><strong>Paste your embed tag</strong><span style="color: rgba(10,10,10,0.6);"> - one line in your site''s &lt;head&gt;. It loads on every page automatically.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">2.</td><td style="padding: 8px 0;"><strong>Send your client the link</strong><span style="color: rgba(10,10,10,0.6);"> - they record right on the site. No login, no download.</span></td></tr><tr><td style="padding: 8px 12px 8px 0; vertical-align: top; color: #0A0A0A; font-weight: 700;">3.</td><td style="padding: 8px 0;"><strong>Open the session</strong><span style="color: rgba(10,10,10,0.6);"> - the AI has already turned it into tasks with replays and estimates.</span></td></tr></table><p style="margin: 0 0 18px 0;">Stuck on the install? Just reply — a real person (often me) reads every one.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Grab your embed code →</a></p><p style="margin: 0 0 4px 0;">Mahmoud</p><p style="margin: 0; color: rgba(10,10,10,0.4); font-size: 13px;">Founder, givefeedback.dev</p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', 'onboarding@givefeedback.dev', CAST(strftime('%s','now') AS INTEGER), CAST(strftime('%s','now') AS INTEGER)),
  ('tpl_02', 'first-feedback', 'Projects · First feedback 🎉', 'You just got your first feedback on {{project}} 🎉', '<span style="display:none;max-height:0;overflow:hidden;">Your first {{session_type}} session on {{project}} is in.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 32px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 16px 0;">🎉 Your very first feedback just landed on <strong>{{project}}</strong>. Here''s what your client left as a {{session_type}} session.</p><div style="border-left: 3px solid #BFFF00; padding-left: 14px; margin: 0 0 20px 0; color: rgba(10,10,10,0.75);">{{feedback_text}}{{transcript_preview}}</div><p style="margin: 0 0 20px 0; color: rgba(10,10,10,0.6);">Open the session to watch the full recording and let AI extract the tasks.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard/projects/{{project_id}}/sessions/{{session_id}}" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Review session →</a></p><p style="margin: 0; color: rgba(10,10,10,0.35); font-size: 12px; text-align: center;"><a href="https://app.givefeedback.dev/dashboard/settings/notifications" target="_blank" style="color: rgba(10,10,10,0.35); text-decoration: underline;">Manage notifications</a></p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', 'projects@givefeedback.dev', CAST(strftime('%s','now') AS INTEGER), CAST(strftime('%s','now') AS INTEGER)),
  ('tpl_03', 'new-feedback', 'Projects · New feedback notification', 'New {{session_type}} feedback on {{project}}', '<span style="display:none;max-height:0;overflow:hidden;">New {{session_type}} feedback on {{project}}</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 32px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 16px 0;">Someone just left {{session_type}} feedback on <strong>{{project}}</strong>.</p><div style="border-left: 3px solid #BFFF00; padding-left: 14px; margin: 0 0 20px 0; color: rgba(10,10,10,0.75);">{{feedback_text}}{{transcript_preview}}</div><p style="margin: 0 0 20px 0; color: rgba(10,10,10,0.6);">Open the session to see the full recording and let AI extract the tasks.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard/projects/{{project_id}}/sessions/{{session_id}}" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Review session →</a></p><p style="margin: 0; color: rgba(10,10,10,0.35); font-size: 12px; text-align: center;"><a href="https://app.givefeedback.dev/dashboard/settings/notifications" target="_blank" style="color: rgba(10,10,10,0.35); text-decoration: underline;">Manage notifications</a></p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', 'projects@givefeedback.dev', CAST(strftime('%s','now') AS INTEGER), CAST(strftime('%s','now') AS INTEGER)),
  ('tpl_04', 'weekly-digest', 'Projects · Weekly digest', 'Your week on {{project}}', '<span style="display:none;max-height:0;overflow:hidden;">A quick recap of this week''s sessions and tasks on {{project}}.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 32px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 16px 0;">Hi {{name}},</p><p style="margin: 0 0 18px 0;">Here''s what happened on <strong>{{project}}</strong> this week — new sessions came in and the AI turned them into tasks waiting for you.</p><p style="margin: 0 0 20px 0; color: rgba(10,10,10,0.6);">Open the project to review the replays and move the tasks into your sprint.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">Open {{project}} →</a></p><p style="margin: 0; color: rgba(10,10,10,0.35); font-size: 12px; text-align: center;"><a href="https://app.givefeedback.dev/dashboard/settings/notifications" target="_blank" style="color: rgba(10,10,10,0.35); text-decoration: underline;">Manage notifications</a></p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', 'projects@givefeedback.dev', CAST(strftime('%s','now') AS INTEGER), CAST(strftime('%s','now') AS INTEGER)),
  ('tpl_05', 'monthly-update', 'Marketing · Monthly product update', 'What''s new at GiveFeedback: {{feature}}', '<span style="display:none;max-height:0;overflow:hidden;">This month: {{feature}} — plus what''s next.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 32px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 16px 0;">Hi {{name}},</p><p style="margin: 0 0 18px 0;">Big one this month: <strong>{{feature}}</strong>. It''s live in your dashboard now — no setup needed.</p><p style="margin: 0 0 18px 0;">We ship based on what you tell us, so keep the requests coming. Every one is read by a human.</p><p style="margin: 0 0 28px 0; text-align: center;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/dashboard" target="_blank" style="color: #0A0A0A; background-color: #BFFF00; border-radius: 8px; display: inline-block; padding: 10px 24px; text-decoration: none; font-weight: 700; font-size: 14px;">See what''s new →</a></p><p style="margin: 0 0 4px 0;">Mahmoud</p><p style="margin: 0; color: rgba(10,10,10,0.4); font-size: 13px;">Founder, givefeedback.dev</p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0 0 4px 0;"><a rel="noopener noreferrer" href="https://app.givefeedback.dev/unsubscribe" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: underline;">Unsubscribe</a> from product updates</p><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', 'marketing@givefeedback.dev', CAST(strftime('%s','now') AS INTEGER), CAST(strftime('%s','now') AS INTEGER)),
  ('tpl_06', 'support-followup', 'Support · Follow-up', 'Following up on your GiveFeedback ticket', '<span style="display:none;max-height:0;overflow:hidden;">Just checking the issue you flagged is fully sorted.</span><div style="background-color: #F2F0ED; font-family: Inter, system-ui, sans-serif; font-size: 15px; line-height: 1.75; color: #0A0A0A; padding: 32px 28px; text-align: left;"><p style="margin: 0 0 16px 0; font-size: 14px; font-weight: 800; letter-spacing: -0.3px; text-transform: uppercase; color: #0A0A0A;">✦ GIVEFEEDBACK</p><p style="margin: 0 0 16px 0;">Hi {{name}},</p><p style="margin: 0 0 18px 0;">Circling back on the issue you flagged — did our last reply sort it out on your end?</p><p style="margin: 0 0 18px 0;">If you''re still stuck, just reply and we''ll dig back in. If it''s resolved, no need to do anything.</p><p style="margin: 0;">Thanks for helping us make GiveFeedback better.</p></div><div style="background-color: #E8E6E3; font-family: Inter, system-ui, sans-serif; font-size: 12px; color: rgba(10,10,10,0.35); padding: 14px 28px; text-align: center;"><p style="margin: 0;">© 2026 givefeedback.dev · <a rel="noopener noreferrer" href="https://givefeedback.dev" target="_blank" style="color: rgba(10,10,10,0.5); text-decoration: none;">givefeedback.dev</a></p></div>', 'support@givefeedback.dev', CAST(strftime('%s','now') AS INTEGER), CAST(strftime('%s','now') AS INTEGER));

